package com.jb.radar;
import java.util.*;
/** Core rebuild rules: finite sensor estimates, shared missile channels and explicit seeker acquisition. */
public class RebuildTest {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static class Certain extends Random {public double nextDouble(){return 0;}public double nextGaussian(){return 0;}}
 static Game game(String... entries){Properties p=new Properties();p.setProperty("radar.retainTracks","false");for(int i=0;i<entries.length;i+=2)p.setProperty(entries[i],entries[i+1]);Game g=new Game(10,new Economy(new Economy.MemoryStore()),new Equipment(p));g.start();g.contacts.clear();g.enemyMissiles.clear();g.random=new Certain();return g;}
 static Game.Contact contact(Game g,int id,double x){Game.Contact t=new Game.Contact();t.id=id;t.x=t.px=x;t.y=t.py=0;t.alt=t.palt=3000;t.heading=t.pheading=-Math.PI/2;t.seen=g.elapsed;t.samples=4;t.quality=1;t.radarTracked=true;t.hadTrack=true;g.contacts.add(t);return t;}
 static Game.Missile launch(Game g,Game.Contact t){check(g.launchBlock(t)==null,"launch eligible: "+g.launchBlock(t));int count=g.missiles.size();g.launch(t);check(g.missiles.size()==count+1,"one missile launched");return g.missiles.get(count);}
 static void align(Game.Missile m,Game.Contact t){MissileMotion.aim(m,t.x-m.x,t.y-m.y,t.alt/1000-m.z);}
 static void firstObservations(){Game g=game();Game.Contact t=new Game.Contact();t.id=1;t.x=10;t.alt=3000;t.speed=1000;t.heading=2;g.contacts.add(t);g.observe(t);check(g.trackStage(t)==Game.TrackStage.ACQUIRING,"first observation acquires");check(t.pspeed==0&&g.speedText(t).equals("---")&&g.directionText(t).equals("---"),"first detection cannot know velocity");g.elapsed=5;check(g.displayX(t)==t.px&&g.displayY(t)==t.py,"no acquiring prediction");t.x=9;g.observe(t);check(g.stableTrack(t),"successive observations stabilize");check(Math.abs(t.pspeed-720)<1e-8&&Math.abs(t.pheading+Math.PI/2)<1e-8,"velocity inferred from measured displacement");check(g.identity(t)==0,"stable track does not identify enemy");g.elapsed=7;double predicted=g.displayX(t);t.x=20;t.heading=0;t.speed=3500;check(g.displayX(t)==predicted,"prediction never reads hidden movement");t.missed=1;t.missedAt=g.elapsed;check(g.trackStage(t)==Game.TrackStage.COASTING&&!g.stableTrack(t)&&g.launchBlock(t).equals("TRACK TOO WEAK"),"coasting cannot fire");g.elapsed=8;check(Math.abs(g.displayX(t)-(predicted-Math.abs(t.pspeed)/3600))<1e-8,"coasting advances only the cached estimate, not hidden target truth");g.elapsed=28;g.maintainTracks();check(g.trackStage(t)==Game.TrackStage.LOST&&!g.tracked(t)&&g.visible(t),"lost frees slot and leaves brief last-known plot");t.x=8;g.observe(t);check(t.samples==1&&g.trackStage(t)==Game.TrackStage.ACQUIRING,"lost reacquires from first observation");}
 static void priority(){Game g=game("radar.tracks","2","radar.channels","2");Game.Contact player=contact(g,1,8),locked=contact(g,2,9);player.priority=true;GameTest.lock(g,locked);Game.Contact ordinary=contact(g,3,4);Game.EnemyMissile incoming=new Game.EnemyMissile();incoming.id=101;incoming.x=incoming.px=15;incoming.alt=incoming.palt=3000;incoming.samples=4;incoming.seen=g.elapsed;incoming.quality=1;g.enemyMissiles.add(incoming);g.maintainTracks();check(g.tracked(locked)&&g.tracked(incoming)&&!g.tracked(player)&&!g.tracked(ordinary),"protected then incoming outrank player");g.release(locked);g.maintainTracks();check(g.tracked(incoming)&&g.tracked(player),"player priority outranks ordinary aircraft");}
 static void separateCapacity(){Game g=game("radar.channels","2");Game.Contact first=contact(g,1,10),second=contact(g,2,11);GameTest.lock(g,first);check(g.lockBlock(second)==null,"lock itself does not consume missile capacity");Game.Missile s1=launch(g,first),s2=launch(g,first);check(g.channels()==2,"two SARH missiles share target but each consumes a channel");g.weapon=g.equipment.active;g.chosenLauncher=1;check(g.launchWarning(second)!=null,"mixed-guidance overflow consequence visible");int count=g.shots;g.launch(second,false);check(g.shots==count,"unconfirmed transfer launches nothing");g.launch(second,true);Game.Missile a=g.missiles.get(2);check(s1.supportReleased&&!g.guided(s1)&&g.guided(s2)&&a.datalink&&g.channels()==2,"active launch can explicitly transfer oldest SARH channel");g.releaseSupport(a);check(g.channels()==1&&!a.datalink&&a.seekerState==Game.SeekerState.SEARCHING,"explicit active release triggers independent search");}
 static void supportRecovery(){Game g=game();Game.Contact t=contact(g,1,10);GameTest.lock(g,t);Game.Missile m=launch(g,t);g.release(t);double cachedX=m.estimateX;for(int i=0;i<10;i++)g.fly(m,.1);check(m.alive&&m.supportLostFor>.9&&g.missileState(m).contains("SUPPORT LOST"),"SARH coasts during recovery window");check(m.estimateX==cachedX,"unsupported SARH retains cached estimate");GameTest.lock(g,t);g.fly(m,.1);check(m.alive&&m.supportLostFor==0&&g.guided(m),"SARH illumination recovery");g.release(t);for(int i=0;i<42;i++)g.fly(m,.1);check(!m.alive,"SARH recovery timeout ends engagement");
  g=game();g.weapon=g.equipment.active;t=contact(g,1,20);m=launch(g,t);t.radarTracked=false;g.fly(m,.1);check(m.alive&&g.channels()==0&&!m.datalink&&m.seekerState==Game.SeekerState.SEARCHING,"lost active updates activate fallback search and release channel");t.radarTracked=true;g.fly(m,.1);check(!m.datalink&&m.seekerState==Game.SeekerState.SEARCHING,"searching missile does not silently resume external guidance");for(int i=0;i<65&&m.alive;i++)g.fly(m,.1);check(!m.alive,"no seeker acquisition means finite search timeout");}
 static void estimateIsolation(){Game a=game(),b=game();a.weapon=a.equipment.active;b.weapon=b.equipment.active;Game.Contact ta=contact(a,1,20),tb=contact(b,1,20);Game.Missile ma=launch(a,ta),mb=launch(b,tb);ta.x=23;ta.y=10;ta.alt=7000;tb.x=-15;tb.y=20;tb.alt=10000;for(int i=0;i<10;i++){a.fly(ma,.1);b.fly(mb,.1);}check(ma.seekerState==Game.SeekerState.MIDCOURSE&&mb.seekerState==Game.SeekerState.MIDCOURSE,"still midcourse");check(Math.abs(ma.x-mb.x)<1e-10&&Math.abs(ma.y-mb.y)<1e-10&&Math.abs(ma.z-mb.z)<1e-10,"midcourse flight independent of hidden target truth");}
 static void seeker(){Game g=game();g.weapon=g.equipment.active;Game.Contact t=contact(g,1,12);Game.Missile m=launch(g,t);m.x=8;m.z=3;MissileMotion.aim(m,-1,0,0);check(!g.guided(m)&&m.seekerState==Game.SeekerState.SEARCHING&&!m.autonomous,"transmitting does not imply acquisition outside FOV");check(g.missileState(m).equals("SEARCHING")&&g.guidanceLine(m)!=Game.GuidanceLine.TARGET_SOLID,"search has no confirmed seeker line");align(m,t);for(int i=0;i<20&&!m.autonomous;i++)g.fly(m,.025);check(g.guided(m)&&m.autonomous&&m.seekerState==Game.SeekerState.ACQUIRED,"assigned target acquires within seeker envelope");check(g.midcourseUsed()==0&&g.missileState(m).equals("SEEKER LOCK"),"autonomous acquisition leaves channel released");t.radarTracked=false;g.battery.parts[Battery.POWER].hp=0;check(g.guided(m),"acquired seeker independent of battery");t.y=20;g.fly(m,.05);check(!m.autonomous&&m.seekerState==Game.SeekerState.SEARCHING&&g.guidanceLine(m)==Game.GuidanceLine.NONE,"seeker loss clears confirmed line");for(int i=0;i<125;i++)g.fly(m,.05);check(!m.alive,"failed seeker search times out");}
 static void searchReleasesSupport(){Game g=game();g.weapon=g.equipment.active;Game.Contact t=contact(g,1,12);Game.Missile m=launch(g,t);m.x=8;m.z=3;t.y=20;align(m,newStationaryAim(12,0,3000));for(int i=0;i<45;i++)g.fly(m,.1);check(m.alive&&m.seekerState==Game.SeekerState.SEARCHING&&m.searchAge>4,"seeker search still within configured six seconds");check(!m.datalink&&!m.linkReserved&&g.channels()==0,"searching releases external guidance while finite seeker search continues");}
 static Game.Contact newStationaryAim(double x,double y,double alt){Game.Contact t=new Game.Contact();t.x=x;t.y=y;t.alt=alt;return t;}
 static void rangeLimits(){Game g=game("radar.detectionAbsoluteKm","36","radar.trackingAbsoluteKm","28","radar.lockAbsoluteKm","20");Game.Contact t=contact(g,1,33);t.alt=t.palt=6000;double marginal=g.signal(t);check(marginal>0&&marginal<g.rangeFactor(20,30,36),"detection quality declines beyond effective");t.x=36.01;check(g.signal(t)==0,"absolute detection hard boundary");t.x=t.px=25;t.samples=4;g.maintainTracks();check(g.tracked(t)&&g.trackQuality(t)<1,"track may extend explicitly beyond nominal");t.px=29;g.maintainTracks();check(!g.tracked(t),"absolute track hard boundary");}
 public static void main(String[] args){firstObservations();priority();separateCapacity();supportRecovery();estimateIsolation();seeker();searchReleasesSupport();rangeLimits();System.out.println("PASS: acquiring/stable/coasting/lost estimates, priority, shared missile channels, explicit release, support recovery, seeker FOV/acquisition/loss, hidden-truth isolation and absolute limits");}
}
